function makeCtx(workingDir: string): ToolContext {
  return {
    workingDir,
    sessionId: "test",
    stepIndex: 0,
    signal: new AbortController().signal,
  };
}

describe("os.fs.hash", () => {
  let dir: string;
  beforeEach(async () => {
    dir = await mkdtemp(join(tmpdir(), "atomic-hash-"));
  });
  afterEach(async () => {
    await rm(dir, { recursive: true, force: true });
  });

  it("computes SHA-256 by default", async () => {
    const path = join(dir, "a.txt");
    await writeFile(path, "hello omnissiah", "utf8");
    const expected = createHash("sha256")
      .update("hello omnissiah")
      .digest("hex");
    const result = await osFsHashTool.run({ path: "a.txt" }, makeCtx(dir));
    expect(result.status).toBe("ok");
    expect(result.details.digest).toBe(expected);
    expect(result.details.algorithm).toBe("sha256");
    expect(result.summary).toContain(expected);
  });

  it("honours an explicit algorithm", async () => {
    const path = join(dir, "b.txt");
    await writeFile(path, "magos", "utf8");
    const md5 = createHash("md5").update("magos").digest("hex");
    const result = await osFsHashTool.run(
      { path: "b.txt", algorithm: "md5" },
      makeCtx(dir),
    );
    expect(result.details.digest).toBe(md5);
  });

  it("supports base64 encoding", async () => {
    const path = join(dir, "c.txt");
    await writeFile(path, "sacred circuit", "utf8");
    const expected = createHash("sha1")
      .update("sacred circuit")
      .digest("base64");
    const result = await osFsHashTool.run(
      { path: "c.txt", algorithm: "sha1", encoding: "base64" },
      makeCtx(dir),
    );
    expect(result.details.digest).toBe(expected);
    expect(result.details.encoding).toBe("base64");
  });

  it("streams a large file without buffering it all", async () => {
    const path = join(dir, "big.bin");
    // 2 MB of deterministic content built from a repeating pattern.
    const chunk = Buffer.alloc(64 * 1024, 0xab);
    const parts: Buffer[] = [];
    for (let i = 0; i < 32; i++) parts.push(chunk);
    const full = Buffer.concat(parts);
    await writeFile(path, full);
    const expected = createHash("sha512").update(full).digest("hex");
    const result = await osFsHashTool.run(
      { path: "big.bin", algorithm: "sha512" },
      makeCtx(dir),
    );
    expect(result.details.digest).toBe(expected);
    expect(result.details.size).toBe(full.length);
  });

  it("rejects an unknown algorithm", async () => {
    const path = join(dir, "x.txt");
    await writeFile(path, "hi", "utf8");
    await expect(
      osFsHashTool.run({ path: "x.txt", algorithm: "whirlpool" }, makeCtx(dir)),
    ).rejects.toThrow(/unknown algorithm/);
  });

  it("rejects when path is a directory", async () => {
    await expect(osFsHashTool.run({ path: "." }, makeCtx(dir))).rejects.toThrow(
      /not a regular file/,
    );
  });
});

import type { CompressedToolResult } from "../compressor/result-compressor.js";
import { coerceToolArgs } from "./coerce-tool-args.js";
import type { ToolRole } from "./tool-roles.js";

export interface ToolContext {
  /** Working directory for OS tools and relative path resolution. */
  workingDir: string;
  sessionId: string;
  stepIndex: number;
  signal: AbortSignal;
  /**
   * The turn's tool role (`tool-roles.ts`), when the step knows it.
   * `tool.view` reads it to tell a tool that is already described in
   * full for this role (nothing to load) from one outside the role
   * (load it). Absent ⇒ `full`.
   */
  toolRole?: ToolRole;
  /**
   * Absolute paths the user named in this session's own messages
   * (`userNamedPaths`, `src/tools/read-scope/`), recomputed by the step
   * from the transcript. Under `agent.readScope: "working-dir"` a read
   * may go under any of these as well as under `workingDir`. Absent ⇒
   * nothing named.
   */
  readRoots?: readonly string[];
  /**
   * The provider id this step's completions are pinned to
   * (`StepDependencies.providerId` — a fusion worker runs on the local
   * leg). Absent ⇒ the step runs on the active text provider. Read by
   * tools that call a model themselves (`vision.describe`) so they talk
   * to the provider serving the step, not the one active at boot.
   */
  providerId?: string;
}

export interface ToolDefinition {
  name: string;
  description: string;
  readonly: boolean;
  run: (
    args: Record<string, unknown>,
    ctx: ToolContext,
  ) => Promise<CompressedToolResult>;
}

export class ToolNotFoundError extends Error {
  constructor(name: string) {
    super(`tool not registered: ${name}`);
    this.name = "ToolNotFoundError";
  }
}

/**
 * Tool registry: the agent loop calls `invoke()` and the registry takes
 * care of dispatch. Individual tools live in their own files and are
 * registered explicitly (no dynamic discovery).
 */
export class ToolRegistry {
  private readonly tools = new Map<string, ToolDefinition>();

  register(definition: ToolDefinition): void {
    this.tools.set(definition.name, definition);
  }

  /**
   * Remove a tool by name. Returns `true` when a tool was actually
   * unregistered, `false` when the name was not known. Used by the
   * MCP manager to detach a server's tools cleanly on stop /
   * restart — the static native tools never call this.
   */
  unregister(name: string): boolean {
    return this.tools.delete(name);
  }

  list(): ToolDefinition[] {
    return Array.from(this.tools.values());
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  get(name: string): ToolDefinition {
    const tool = this.tools.get(name);
    if (!tool) throw new ToolNotFoundError(name);
    return tool;
  }

  async invoke(
    name: string,
    args: Record<string, unknown>,
    ctx: ToolContext,
  ): Promise<CompressedToolResult> {
    const tool = this.get(name);
    // Models sometimes emit a JSON value one level over-encoded (a
    // number as "200000", an array as "[\"a.png\"]"). Unwrap those
    // before dispatch; anything that cannot be coerced is passed
    // through untouched so the tool reports its own error.
    return tool.run(coerceToolArgs(name, args), ctx);
  }
}

import type { DangerousToolOptions } from "../../approval/dangerous-tool.js";
import type { ReadScope } from "../../config/index.js";
import { isFusionWorkerSessionId } from "../../session/fusion-worker-session.js";
import type { ToolDefinition, ToolRegistry } from "../tool-registry.js";
import {
  checkWorkerRead,
  findSessionReadOutside,
  workerReadRefusal,
} from "./read-scope.js";
import {
  ReadOutsideApprover,
  readOutsidePrompt,
  shellReadOutsidePrompt,
} from "./read-scope-approval.js";
import {
  findShellPathOutsideScope,
  shellCommandLine,
  type ShellScopeEnv,
} from "./read-scope-shell.js";
import { READ_TOOL_TARGETS, SHELL_TOOL } from "./read-scope-targets.js";

export interface ConfineReadsOptions {
  /** The directories a fusion worker's fan-out may write in. */
  grantedDirs: (sessionId: string) => readonly string[];
  /**
   * The live `agent.readScope`. Read on every call, so a config change
   * takes effect without a restart. Omitted: only fusion workers are
   * confined and the shell is not wrapped — the pre-v67 install
   * (`confineWorkerReads`).
   */
  readScope?: () => ReadScope;
  /**
   * The ladder a read outside the scope asks through (`fs_read_outside`,
   * `read-scope-approval.ts`). Required with `readScope`: the session
   * scope is a question, and a question needs a gate — an install that
   * forgot the gate would silently be a refusal, which is exactly the
   * half-wiring the throw below exists to catch.
   */
  approvals?: DangerousToolOptions;
  /** The shell check's notion of home and platform; a test seam. */
  shellEnv?: ShellScopeEnv;
}

/** Definitions this module produced, so a second install does not wrap twice. */
const CONFINED = new WeakSet<ToolDefinition>();

/**
 * Wrap every registered read-class tool (and, under a session scope, the
 * shell) so a call is checked before it runs. Call once, after the
 * native tools are registered. Returns the names it confined.
 *
 * Wrapping at the registry rather than inside each tool keeps the rule
 * in one place, and `registry.invoke` is the single path every call —
 * native, batched, or recovered from text — takes. A worker session
 * gets the worker check first (always on, a refusal); then, when the
 * scope is `working-dir`, every other session's call outside the roots
 * is asked about, and runs or is refused by the answer.
 */
export function confineReads(
  registry: Pick<ToolRegistry, "has" | "get" | "register">,
  options: ConfineReadsOptions,
): string[] {
  if (options.readScope !== undefined && options.approvals === undefined) {
    throw new Error(
      "confineReads: a session read scope asks through the approval ladder; pass `approvals` with `readScope`",
    );
  }
  const asker =
    options.approvals === undefined
      ? null
      : new ReadOutsideApprover(options.approvals);
  const confined: string[] = [];
  const scoped = () => options.readScope?.() === "working-dir";
  const install = (name: string, run: ToolDefinition["run"]): void => {
    const inner = registry.get(name);
    confined.push(name);
    if (CONFINED.has(inner)) return;
    const wrapped: ToolDefinition = { ...inner, run };
    CONFINED.add(wrapped);
    registry.register(wrapped);
  };

  for (const name of READ_TOOL_TARGETS.keys()) {
    if (!registry.has(name)) continue;
    const inner = registry.get(name);
    install(name, async (args, ctx) => {
      const worker = checkWorkerRead(
        name,
        args,
        ctx,
        options.grantedDirs(ctx.sessionId),
      );
      if (worker !== null) return worker;
      if (asker === null || !scoped()) return inner.run(args, ctx);
      const refusal = await asker.admit(
        name,
        ctx,
        (roots) => findSessionReadOutside(name, args, ctx, roots),
        (path, root) => readOutsidePrompt(path, ctx.workingDir, root),
      );
      return refusal ?? inner.run(args, ctx);
    });
  }

  if (asker !== null && registry.has(SHELL_TOOL)) {
    const inner = registry.get(SHELL_TOOL);
    install(SHELL_TOOL, async (args, ctx) => {
      if (!scoped()) return inner.run(args, ctx);
      if (isFusionWorkerSessionId(ctx.sessionId)) {
        // A worker's world is its task's directories, and there is
        // nobody to ask: the refusal, as for its reads.
        const granted = options.grantedDirs(ctx.sessionId);
        const outside = findShellPathOutsideScope(
          args,
          ctx,
          [ctx.workingDir, ...granted],
          options.shellEnv,
        );
        return outside === null
          ? inner.run(args, ctx)
          : workerReadRefusal(SHELL_TOOL, outside, ctx, granted);
      }
      const refusal = await asker.admit(
        SHELL_TOOL,
        ctx,
        (roots) => findShellPathOutsideScope(args, ctx, roots, options.shellEnv),
        (path, root) =>
          shellReadOutsidePrompt(
            shellCommandLine(args),
            path,
            ctx.workingDir,
            root,
          ),
      );
      return refusal ?? inner.run(args, ctx);
    });
  }
  return confined;
}

/**
 * The fusion-only install: workers confined to their working directory
 * and fan-out scope, every other session untouched, the shell not
 * wrapped. Kept for callers that want exactly that; the runtime installs
 * `confineReads` with the live `agent.readScope` and the ladder instead.
 */
export function confineWorkerReads(
  registry: Pick<ToolRegistry, "has" | "get" | "register">,
  options: { grantedDirs: (sessionId: string) => readonly string[] },
): string[] {
  return confineReads(registry, { grantedDirs: options.grantedDirs });
}

